import networkx as nx

# For connected graphs with n >= 2:
# Is radius(G) + 1 <= roman_domination_number(G)?

def roman_domination_number(G):
    # MIP or brute force
    import itertools
    nodes = list(G.nodes())
    n = len(nodes)
    best = 2 * n
    for f in itertools.product([0, 1, 2], repeat=n):
        # check condition
        f_map = dict(zip(nodes, f))
        valid = True
        for v in nodes:
            if f_map[v] == 0:
                if not any(f_map[u] == 2 for u in G.neighbors(v)):
                    valid = False
                    break
        if valid:
            weight = sum(f)
            if weight < best:
                best = weight
    return best

for n in range(2, 9):
    print(f'Checking n={n}...')
    for G in nx.graph_atlas_g():
        if G.number_of_nodes() == n and nx.is_connected(G):
            rad = nx.radius(G)
            gamma_R = roman_domination_number(G)
            if rad + 1 > gamma_R:
                print(f'COUNTEREXAMPLE found! n={n}, rad={rad}, gamma_R={gamma_R}, edges={list(G.edges())}')
                break
    else:
        continue
    break
